mod kinship;
use std::io::{BufRead,Write};
fn main(){for line in std::io::stdin().lock().lines(){let line=line.unwrap();let mut t=line.split_whitespace();let op=t.next().unwrap();let n:usize=t.next().unwrap().parse().unwrap();let p:usize=t.next().unwrap().parse().unwrap();let m:usize=t.next().unwrap().parse().unwrap();let mut rows=Vec::new();for _ in 0..n{rows.push((0..p).map(|_|t.next().unwrap().parse::<f64>().unwrap()).collect::<Vec<_>>());}let args=(0..m).map(|_|t.next().unwrap().parse::<f64>().unwrap()).collect::<Vec<_>>();match kinship::run(op,&rows,&args){Ok(j)=>println!("{}",j),Err(e)=>println!("ERROR:{}",e)}std::io::stdout().flush().unwrap();}}
